NSOLIDATED_INTERMEDIATE AS select upper(ACCOUNT_NAME) ACCOUNT_NAME ,ACCOUNT_ID ,upper(CAMPAIGN_NAME) CAMPAIGN_NAME ,CAMPAIGN_ID ,NULL AS CAMPAIGN_TYPE ,upper(ADSET_NAME) ADSET_NAME ,ADSET_ID ,AD_ID ,upper(AD_NAME) AD_NAME ,DATE ,NULL AD_TYPE ,NULL AD_STRENGTH ,NULL AD_NETWORK_TYPE ,NULL AD_URL ,DAYNAME(DATE) Day_of_Week ,YEAR(DATE) AS YEAR1 ,MONTH(DATE) AS MONTH1 ,upper(CHANNEL) CHANNEL ,upper(ACCOUNT) ACCOUNT ,link_clicks as clicks ,Spend ,Impressions ,Conversions ,Conversion_Value ,Add_to_carts ,Add_to_cart_value ,Landing_page_views ,Initiate_checkouts ,Initiate_checkouts_value from EMMASLEEP_DB.MAPLEMONK.EMMASLEEP_DB_FACEBOOK_CONSOLIDATED union select upper(ACCOUNT_NAME) ACCOUNT_NAME ,ACCOUNT_ID ,upper(CAMPAIGN_NAME) CAMPAIGN_NAME ,CAMPAIGN_ID ,case when UPPER(campaign_name) like (\'%PERFORMANCE-MAX%\') then \'PERFORMANCE MAX\' when UPPER(campaign_name) like (\'%DEMAND-GEN%\') then \'VIDEO DEMAND GEN\' else \'SEARCH & VIDEO\' end as CAMPAIGN_TYPE ,upper(ADSET_NAME) ADSET_NAME ,ADSET_ID ,AD_ID ,upper(AD_NAME) AD_NAME ,Date ,AD_TYPE ,AD_STRENGTH ,AD_NETWORK_TYPE ,AD_FINAL_URL ,Day_of_Week ,\"YEAR\" YEAR1 ,\"MONTH\" MONTH1 ,upper(CHANNEL) CHANNEL ,upper(ACCOUNT) ACCOUNT ,clicks ,spend ,impressions ,conversions ,conversion_value ,null as Add_to_carts ,null as Add_to_cart_value ,null as Landing_page_views ,null as Initiate_checkouts ,null as Initiate_checkouts_value from EMMASLEEP_DB.MAPLEMONK.EMMASLEEP_DB_GOOGLEADS_CONSOLIDATED Union Select NULL AS ACCOUNT_NAME ,PROFILEID ,upper(CAMPAIGNNAME) CAMPAIGN_NAME ,CAMPAIGNID ,NULL as CAMPAIGN_TYPE ,upper(adGroupName) adGroupName ,adGroupId ,ADID ,NULL AS AD_NAME ,DATE ,CAMPAIGN_TYPE ,NULL AS AD_STRENGTH ,NULL AS AD_NETWORK_TYPE ,NULL AS AD_URL ,dayname(try_to_date(date)) DAY_OF_WEEK ,year(try_to_date(date)) YEAR1 ,month(try_to_date(date)) MONTH1 ,\'AMAZON\' AS CHANNEL ,NULL AS ACCOUNT ,CLICKS ,SPEND ,IMPRESSIONS ,CONVERSIONS ,AdSales ,NULL AS ADD_TO_CARTS ,NULL AS ADD_TO_CART_VALUE ,NULL AS LANDING_PAGE_VIEWS ,null as Initiate_checkouts ,null as Initiate_checkouts_value FROM EMMASLEEP_DB.MAPLEMONK.EMMASLEEP_DB_AMAZONADS_MARKETING ; CREATE OR REPLACE TABLE EMMASLEEP_DB.MAPLEMONK.EMMASLEEP_DB_MARKETING_CONSOLIDATED AS WITH state_ga_sessions as( select TO_DATE(DATE, \'YYYYMMDD\') session_date, region ga_state, country, sum(sessions) as sessions from EMMASLEEP_DB.MAPLEMONK.EMMASLEEP_LOCATIONS group by 1,2,3 union all select TO_DATE(DATE, \'YYYYMMDD\') session_date, \'REST OF INDIA\' as ga_state, country, sum(sessions) as sessions from EMMASLEEP_DB.MAPLEMONK.EMMASLEEP_LOCATIONS where upper(country) = \'INDIA\' and UPPER(region) not in (\'KERALA\',\'KARNATAKA\',\'TAMIL NADU\',\'TELANGANA\',\'ANDHRA PRADESH\',\'MAHARASHTRA\',\'DELHI\') group by 1,2,3 ) select a.ACCOUNT_NAME ,a.ACCOUNT_ID ,a.CAMPAIGN_NAME ,a.CAMPAIGN_TYPE ,c.\"Country Name\" ,CASE WHEN NOT(a.CAMPAIGN_NAME LIKE ANY (\'(IN)<00_MAT>[SEARCH-BRAND]{EP}: EMMA MATTRESS\',\'(IN)<00_MAT>[SHOPPING-BRAND]: MATTRESS\')) THEN ( CASE WHEN UPPER(a.CAMPAIGN_NAME) LIKE \'%KERALA%\' THEN \'KERALA\' WHEN UPPER(a.CAMPAIGN_NAME) LIKE \'%TELANGANA/AP%\' OR UPPER(a.CAMPAIGN_NAME) LIKE \'%AP/TELANGANA%\' OR UPPER(a.CAMPAIGN_NAME) LIKE \'%TELANGANA%\' THEN \'TELANGANA\' WHEN (UPPER(a.CAMPAIGN_NAME) LIKE \'%KARNATAKA%\' OR UPPER(a.CAMPAIGN_NAME) LIKE \'%BENGALURU%\' OR UPPER(a.CAMPAIGN_NAME) LIKE \'%BANGALORE%\') THEN \'KARNATAKA\' WHEN UPPER(a.CAMPAIGN_NAME) LIKE \'%TAMIL NADU%\' THEN \'TAMIL NADU\' WHEN UPPER(a.CAMPAIGN_NAME) LIKE \'%MAHARASHTRA%\' OR UPPER(a.CAMPAIGN_NAME) LIKE \'%MH%\' THEN \'MAHARASHTRA\' WHEN UPPER(a.CAMPAIGN_NAME) LIKE \'%DELHI%\' THEN \'DELHI\' WHEN UPPER(a.CAMPAIGN_NAME) LIKE ANY (\'%PAN-INDIA%\',\'%ROI%\',\'%CYBER CIT%\',\'%REST OF INDIA%\',\'%HUNT REGIONS%\',\'%PERFORMANCE-MAX%\',\'%MATTRESS GENERIC%\') THEN \'REST OF INDIA\' ELSE NULL END) ELSE NULL END AS CAMPAIGN_STATE ,a.CAMPAIGN_ID ,a.ADSET_NAME ,a.ADSET_ID ,a.AD_ID ,a.AD_NAME ,coalesce(a.DATE,null) date ,a.AD_TYPE ,a.AD_STRENGTH ,a.AD_NETWORK_TYPE ,a.AD_URL ,a.DAY_OF_WEEK ,a.YEAR1 ,a.MONTH1 ,upper(coalesce(a.CHANNEL, null)) Channel ,a.ACCOUNT ,a.CLICKS ,a.SPEND ,a.IMPRESSIONS ,a.CONVERSIONS ,a.CONVERSION_VALUE ,a.ADD_TO_CARTS ,a.ADD_TO_CART_VALUE ,a.LANDING_PAGE_VIEWS ,a.INITIATE_CHECKOUTS ,a.INITIATE_CHECKOUTS_VALUE ,b.campaign_name shopify_campaign_name ,div0(b.shopify_revenue, count(1) over (partition by coalesce(a.date,b.date), lower(coalesce(a.campaign_name,b.campaign_name)), lower(coalesce(a.channel,b.channel))) ) shopify_revenue ,div0(l.sessions,count(1) over (partition by upper(coalesce(campaign_state,l.ga_state)),coalesce(a.date,l.session_date),upper(coalesce(c.\"Country Name\",l.country))) ) as state_level_sessions ,div0(b.shopify_orders, count(1) over (partition by coalesce(a.date,b.date), lower(coalesce(a.campaign_name,b.campaign_name)), lower(coalesce(a.channel,b.channel))) ) shopify_state_orders ,div0(b.return_amount, count(1) over (partition by coalesce(a.date,b.date), lower(coalesce(a.campaign_name,b.campaign_name)), lower(coalesce(a.channel,b.channel))) ) shopify_return_value from EMMASLEEP_DB.MAPLEMONK.EMMASLEEP_DB_MARKETING_CONSOLIDATED_INTERMEDIATE a full outer join (select order_timestamp::date date ,final_utm_campaign campaign_name ,upper(case when lower(final_utm_channel) like any (\'%paid social%\',\'%facebook%\', \'%instagram%\',\'%ig%\',\'%fb%\') then \'Meta\' when lower(final_utm_channel) like (\'%google%\') then \'Google\' end) channel ,sum(total_sales) shopify_revenue ,sum(total_return_amount) return_amount ,count(distinct s.order_id) shopify_orders from EMMASLEEP_DB.MAPLEMONK.EMMASLEEP_DB_SHOPIFY_FACT_ITEMS s left join emmasleep_db.maplemonk.emmasleep_db_returns_consolidated r on r.saleorderitemcode = s.line_item_id and r.reference_code = replace(s.order_name,\'#\',\'\') where channel is not null group by 1,2,3 ) b on lower(a.campaign_name) = lower(replace(b.campaign_name,\'+\',\' \')) and a.date = b.date and lower(a.channel) = lower(b.channel) left join EMMASLEEP_DB.MAPLEMONK.country_code_mapping_country_marketing_mapping c on lower(trim(c.\"ISO Code\")) = lower(left(a.campaign_name,4)) LEFT JOIN state_ga_sessions l on (l.session_date) = a.date and upper(trim(l.ga_state)) = upper(trim(campaign_state)) and upper(trim(l.country)) = upper(trim(c.\"Country Name\")) ;",
